      "venue_url": "https://www.semanticscholar.org/paper/967bdd5e361f2050a1fa7f82259204058ed0acf4",
      "venue_confidence": "semantic-scholar",
      "venue_source": "semantic-scholar",
      "is_authority_venue": true,
      "ingest_source": "",
